const pageEn = Object.fromEntries(Object.entries(pageEs).map(([english,spanish])=>[spanish,english]));

export function SpanishPageTranslator(){
  const {language}=useLanguage();
  useEffect(()=>{
    const root=document.querySelector(".app");
    if(!root)return;
    const dictionary=language==="es"?pageEs:pageEn;
    const translate=(value)=>{
      const trimmed=value.trim();
      const translated=dictionary[trimmed];
      return translated?value.replace(trimmed,translated):value;
    };
    const visit=(node)=>{
      if(node.nodeType===Node.TEXT_NODE){
        const current=node.nodeValue||"";
        const next=translate(current);
        if(next!==current)node.nodeValue=next;
        return;
      }
      if(node.nodeType!==Node.ELEMENT_NODE)return;
      ["alt","title","aria-label","placeholder"].forEach((name)=>{
        if(!node.hasAttribute(name))return;
        const current=node.getAttribute(name)||"";
        const next=translate(current);
        if(next!==current)node.setAttribute(name,next);
      });
      node.childNodes.forEach(visit);
    };
    visit(root);
    const observer=new MutationObserver((records)=>records.forEach((record)=>{
      if(record.type==="characterData")visit(record.target);
      record.addedNodes.forEach(visit);
    }));
    observer.observe(root,{childList:true,characterData:true,subtree:true});
    return()=>observer.disconnect();
  },[language]);
  return null;
}
